/* ===== RESET & BASE ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #E5E5E5;
  font-family: "Inter", sans-serif;
}

/* ===== AD WRAPPER ===== */
#ad-300x600 {
  width: 300px;
  height: 600px;
  background-color: #FFFFFF;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 8px 32px rgba(0,0,0,0.18);
  cursor: pointer;
  border: 1px solid #CCCCCC;
}

/* ===== HEADER ===== */
.ad-header {
  width: 100%;
  height: 52px;
  background-color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  position: relative;
  z-index: 10;
  flex-shrink: 0;
  border-bottom: 1px solid #E5E5E5;
}

.nike-logo {
  height: 28px;
  width: auto;
  display: block;
  object-fit: contain;
}

.nouveautes-tag {
  font-family: "Barlow Condensed", sans-serif;
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 0.12em;
  color: #FFFFFF;
  background-color: #FA5400;
  padding: 3px 8px;
  text-transform: uppercase;
  border-radius: 2px;
}

/* ===== SLIDE TRACK ===== */
.slide-track {
  width: 1200px; /* 4 × 300px */
  height: 420px;
  display: flex;
  flex-direction: row;
  transition: transform 0.55s cubic-bezier(0.77, 0, 0.175, 1);
  flex-shrink: 0;
}

.slide {
  width: 300px;
  height: 420px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

/* ===== PRODUCT BACKGROUNDS ===== */
.product-bg {
  width: 300px;
  height: 300px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.bg-dark {
  background-color: #111111;
}

.bg-light {
  background-color: #F5F5F5;
}

.bg-neutral {
  background-color: #E5E5E5;
}

.product-img {
  width: 260px;
  height: 260px;
  object-fit: contain;
  display: block;
  animation: floatUp 0.7s cubic-bezier(0.22,1,0.36,1) both;
  transform-origin: center bottom;
}

.product-apparel {
  width: 240px;
  height: 280px;
  object-fit: cover;
  object-position: top center;
}

/* ===== SLIDE COPY ===== */
.slide-copy {
  flex: 1;
  background-color: #FFFFFF;
  padding: 12px 16px 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.slide-label {
  font-family: "Barlow Condensed", sans-serif;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: #FA5400;
  text-transform: uppercase;
}

.slide-headline {
  font-family: "Barlow Condensed", sans-serif;
  font-weight: 700;
  font-size: 28px;
  line-height: 1.0;
  color: #111111;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.slide-sub {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 11px;
  color: #757575;
  line-height: 1.4;
  margin-top: 2px;
}

/* ===== DOTS ===== */
.dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 28px;
  background-color: #FFFFFF;
  flex-shrink: 0;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: none;
  background-color: #CCCCCC;
  cursor: pointer;
  padding: 0;
  transition: background-color 0.3s, transform 0.3s;
  outline: none;
}

.dot.active {
  background-color: #FA5400;
  transform: scale(1.3);
}

/* ===== FOOTER ===== */
.ad-footer {
  width: 100%;
  background-color: #111111;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  position: relative;
  z-index: 10;
}

.cta-btn {
  display: block;
  width: 100%;
  background-color: #FA5400;
  color: #FFFFFF;
  font-family: "Jost", sans-serif;
  font-weight: 700;
  font-size: 13px;
  letter-spacing: 0.06em;
  text-align: center;
  text-decoration: none;
  text-transform: uppercase;
  padding: 11px 16px;
  border-radius: 2px;
  transition: background-color 0.2s, transform 0.15s;
}

.cta-btn:hover {
  background-color: #FFFFFF;
  color: #FA5400;
  transform: translateY(-1px);
}

.cta-btn:active {
  transform: translateY(0);
}

.legal {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 9px;
  color: rgba(255,255,255,0.45);
  text-align: center;
  letter-spacing: 0.04em;
}

/* ===== ACCENT BAR ===== */
.accent-bar {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 3px;
  width: 0%;
  background-color: #FA5400;
  z-index: 20;
  transition: width linear;
}

/* ===== KEYFRAMES ===== */
@keyframes floatUp {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes fadeInHeader {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.ad-header {
  animation: fadeInHeader 0.5s ease both;
}

/* ===== REDUCED MOTION ===== */
@media (prefers-reduced-motion: reduce) {
  .slide-track,
  .cta-btn,
  .dot,
  .accent-bar,
  .product-img {
    transition: none !important;
    animation: none !important;
  }
}

